package au.edu.uow.csci318.planning.application;import au.edu.uow.csci318.planning.domain.StudyPlan;import au.edu.uow.csci318.planning.dto.PlanningDtos.*;import au.edu.uow.csci318.planning.infrastructure.*;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class PlanningApplicationService{private final StudyPlanRepository plans;private final StudyPlanningAgent agent;private final PlanningTools tools;private final ProjectionService projections;private final ObjectMapper json;public PlanningApplicationService(StudyPlanRepository p,StudyPlanningAgent a,PlanningTools t,ProjectionService pr,ObjectMapper j){plans=p;agent=a;tools=t;projections=pr;json=j;}
 @Transactional public PlanResponse generate(PlanRequest request){validatePeriod(request);List<PlanItem>items=agent.generate(request);validateItems(request,items);try{return response(plans.save(new StudyPlan(request.startDate(),request.startDate().plusDays(6),plans.findTopByOrderByCreatedAtDesc().map(x->x.getVersion()+1).orElse(1),json.writeValueAsString(items),"Generated from current incomplete assessments, deadlines, workload and availability.")));}catch(Exception e){throw new IllegalStateException("Plan could not be stored",e);}}
 @Transactional public PlanResponse regenerate(UUID previousId,PlanRequest request){StudyPlan old=plans.findById(previousId).orElseThrow(()->new NoSuchElementException("Study plan not found"));validatePeriod(request);List<PlanItem>items=agent.generate(request);validateItems(request,items);try{List<PlanItem>before=json.readValue(old.getItemsJson(),new TypeReference<>(){});String explanation="Regenerated after current academic state was re-read: "+difference(before,items)+".";return response(plans.save(new StudyPlan(request.startDate(),request.startDate().plusDays(6),old.getVersion()+1,json.writeValueAsString(items),explanation)));}catch(Exception e){throw new IllegalStateException("Plan could not be regenerated",e);}}
 public Optional<PlanResponse>latest(){return plans.findTopByOrderByCreatedAtDesc().map(this::response);}public WorkloadSummary workload(){List<AssessmentView>a=currentAssessments();LocalDate now=LocalDate.now(),weekEnd=now.with(java.time.DayOfWeek.SUNDAY);int incomplete=(int)a.stream().filter(x->"INCOMPLETE".equals(x.status())).count();int dueWeek=(int)a.stream().filter(x->"INCOMPLETE".equals(x.status())&&x.dueDate()!=null&&!x.dueDate().isBefore(now)&&!x.dueDate().isAfter(weekEnd)).count();int due7=(int)a.stream().filter(x->"INCOMPLETE".equals(x.status())&&x.dueDate()!=null&&!x.dueDate().isBefore(now)&&!x.dueDate().isAfter(now.plusDays(7))).count();int mins=a.stream().filter(x->"INCOMPLETE".equals(x.status())).map(AssessmentView::estimatedMinutes).filter(Objects::nonNull).mapToInt(Integer::intValue).sum();int high=(int)a.stream().filter(x->"INCOMPLETE".equals(x.status())&&"HIGH".equals(x.priority())).count();String state=due7>=3||mins>1200?"HIGH":due7>0||mins>480?"MEDIUM":"LOW";return new WorkloadSummary(incomplete,dueWeek,due7,mins,high,state);}
 public ThisWeek thisWeek(){LocalDate from=LocalDate.now().with(java.time.DayOfWeek.MONDAY),to=from.plusDays(6);List<AssessmentView>all=currentAssessments();List<AssessmentView>due=all.stream().filter(a->"INCOMPLETE".equals(a.status())&&a.dueDate()!=null&&!a.dueDate().isBefore(from)&&!a.dueDate().isAfter(to)).sorted(Comparator.comparing(AssessmentView::dueDate)).toList();List<AssessmentView>upcoming=all.stream().filter(a->"INCOMPLETE".equals(a.status())&&a.dueDate()!=null&&a.dueDate().isAfter(to)).sorted(Comparator.comparing(AssessmentView::dueDate)).limit(5).toList();List<StudyProgress>progress;try{progress=tools.getSubjects().stream().map(s->{int done=projections.studied(s.id()),target=s.weeklyStudyTargetMinutes(),remaining=Math.max(0,target-done);String state=done==0?"NO_ACTIVITY":done>=target?"TARGET_REACHED":done*2>=target?"ON_TRACK":"BEHIND_TARGET";return new StudyProgress(s.id(),done,target,remaining,state);}).toList();}catch(Exception e){progress=List.of();}List<PlanItem>items=latest().map(PlanResponse::items).orElse(List.of()).stream().filter(i->!i.date().isBefore(from)&&!i.date().isAfter(to)).toList();return new ThisWeek(from,to,due,upcoming,workload(),progress,items);}
 private List<AssessmentView>currentAssessments(){if(!projections.assessments().isEmpty())return new ArrayList<>(projections.assessments());try{return tools.getIncompleteAssessments();}catch(Exception e){return List.of();}}
 private void validatePeriod(PlanRequest r){if(r.startDate()==null||r.dailyAvailabilityMinutes()==null)throw new IllegalArgumentException("Start date and daily availability are required");for(var e:r.dailyAvailabilityMinutes().entrySet())if(e.getKey().isBefore(r.startDate())||e.getKey().isAfter(r.startDate().plusDays(6))||e.getValue()==null||e.getValue()<0)throw new IllegalArgumentException("Availability must be non-negative and within the seven-day period");}
 private void validateItems(PlanRequest r,List<PlanItem>items){Map<UUID,AssessmentView>known=new HashMap<>();tools.getIncompleteAssessments().forEach(a->known.put(a.id(),a));Map<LocalDate,Integer>daily=new HashMap<>();for(var i:items){AssessmentView a=known.get(i.assessmentId());if(a==null)throw new IllegalArgumentException("Plan references a missing or completed assessment: "+i.assessmentId());if(!a.subjectId().equals(i.subjectId()))throw new IllegalArgumentException("Assessment and subject do not match");if(i.date().isBefore(r.startDate())||i.date().isAfter(r.startDate().plusDays(6)))throw new IllegalArgumentException("Plan item lies outside the requested period");if(i.allocatedMinutes()<=0)throw new IllegalArgumentException("Allocated minutes must be positive");int total=daily.merge(i.date(),i.allocatedMinutes(),Integer::sum);if(total>r.dailyAvailabilityMinutes().getOrDefault(i.date(),0))throw new IllegalArgumentException("Plan exceeds availability on "+i.date());}}
 private String difference(List<PlanItem>a,List<PlanItem>b){Set<UUID>x=new HashSet<>(),y=new HashSet<>();a.forEach(i->x.add(i.assessmentId()));b.forEach(i->y.add(i.assessmentId()));int added=(int)y.stream().filter(i->!x.contains(i)).count(),removed=(int)x.stream().filter(i->!y.contains(i)).count();return added+" assessment(s) added and "+removed+" removed; dates and minutes were recalculated";}
 private PlanResponse response(StudyPlan p){try{return new PlanResponse(p.getId(),p.getStartDate(),p.getEndDate(),p.getVersion(),json.readValue(p.getItemsJson(),new TypeReference<>(){}),p.getExplanation(),p.getCreatedAt());}catch(Exception e){throw new IllegalStateException("Stored plan is unreadable",e);}}
}
